(function () {
 "use strict";
 /* Mobile nav toggle */
 var toggle = document.querySelector(".nav-toggle");
 var navList = document.getElementById("nav-list");
 if (toggle && navList) {
 toggle.addEventListener("click", function () {
 var isOpen = navList.classList.toggle("open");
 toggle.setAttribute("aria-expanded", isOpen ? "true" : "false");
 });
 navList.querySelectorAll("a").forEach(function (link) {
 link.addEventListener("click", function () {
 navList.classList.remove("open");
 toggle.setAttribute("aria-expanded", "false");
 });
 });
 }
 /* Contact form validation */
 var form = document.getElementById("contact-form");
 if (!form) return;
 var status = document.getElementById("form-status");
 var rules = {
 name: function (v) { return v.trim().length > 0 ? "" : "Please enter your name."; },
 email: function (v) {
 if (!v.trim()) return "Please enter your email.";
 var re = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
 return re.test(v.trim()) ? "" : "Please enter a valid email address.";
 },
 project: function (v) { return v ? "" : "Please select a project type."; },
 message: function (v) { return v.trim().length >= 10 ? "" : "Please add a few details (10+ characters)."; }
 };
 function showError(field, message) {
 var input = form.elements[field];
 var errorEl = document.getElementById(field + "-error");
 if (errorEl) errorEl.textContent = message;
 if (input) input.setAttribute("aria-invalid", message ? "true" : "false");
 }
 function validateField(field) {
 var input = form.elements[field];
 var message = rules[field](input.value);
 showError(field, message);
 return !message;
 }
 Object.keys(rules).forEach(function (field) {
 var input = form.elements[field];
 if (!input) return;
 input.addEventListener("blur", function () { validateField(field); });
 input.addEventListener("input", function () {
 if (input.getAttribute("aria-invalid") === "true") validateField(field);
 });
 });
 form.addEventListener("submit", function (e) {
 e.preventDefault();
 var valid = true;
 Object.keys(rules).forEach(function (field) {
 if (!validateField(field)) valid = false;
 });
 if (!valid) {
 status.textContent = "Please fix the highlighted fields before sending.";
 status.className = "form-status error";
 var firstInvalid = form.querySelector('[aria-invalid="true"]');
 if (firstInvalid) firstInvalid.focus();
 return;
 }
 status.textContent = "Signal received. We'll be in touch within one business day.";
 status.className = "form-status success";
 form.reset();
 Object.keys(rules).forEach(function (field) { showError(field, ""); });
 });
})();
